		const storage = memoryStorage(serialized)
		const config = new DeviceConfig(DeviceConfig.Version, storage)

		o(storage.writes).equals(0)
		o(storage.value).equals(serialized)
		o(config.loadAll()).deepEquals(Object.values(expectedCredentials))
		o(config.getSignupToken()).equals("existingToken")
		o(config.getTheme()).equals("dark")
		o(config.getLanguage()).equals("de")
		o(config.hasScheduledAlarmsForUser("internalUserId")).equals(true)
		o(config.getCredentialsEncryptionKey()).deepEquals(new Uint8Array([177, 171, 30, 118, 71, 173]))
		o(config.getTestDeviceId()).equals(Promise.resolve("testDevice"))

		config.setTheme("dark")
		config.setLanguage("de")
		config.setNoAlarmsScheduled()
		o(storage.writes).equals(1)
		o(JSON.parse(storage.value!)._credentials).deepEquals(expectedCredentials)
	})

