		const storage = memoryStorage(JSON.stringify({
			_version: DeviceConfig.Version,
			_credentials: expectedCredentials,
			_signupToken: "existingToken",
		}))
		const config = new DeviceConfig(DeviceConfig.Version, storage)
		config.store({
			credentialInfo: {login: "internal@example.com", userId: "internalUserId", type: "internal"},
			accessToken: "newToken",
			encryptedPassword: "newPassword",
			databaseKey: null,
		})
		o(config.loadByUserId("internalUserId")?.databaseKey).equals("savedDatabaseKey")
		o(JSON.parse(storage.value!)._credentials.internalUserId.databaseKey).equals("savedDatabaseKey")
		o(storage.writes).equals(1)
	})

	o("generates a token once when missing", function () {
		const storage = memoryStorage(JSON.stringify({_version: DeviceConfig.Version, _credentials: {}}))
		const config = new DeviceConfig(DeviceConfig.Version, storage)
		o(storage.writes).equals(1)
		o(config.getSignupToken().length).equals(8)
		o(JSON.parse(storage.value!)._signupToken).equals(config.getSignupToken())
		new DeviceConfig(DeviceConfig.Version, storage)
		o(storage.writes).equals(1)
	})

	o("recovers from invalid JSON and unavailable storage", function () {
		const invalid = memoryStorage("{")
		const config = new DeviceConfig(DeviceConfig.Version, invalid)
		o(config.getSignupToken().length).equals(8)
		o(invalid.writes).equals(1)
		o(JSON.parse(invalid.value!)._credentials).deepEquals({})

		const unavailable = {
			getItem() { throw new Error("unavailable") },
			setItem() { throw new Error("unavailable") },
		}
		o(new DeviceConfig(DeviceConfig.Version, unavailable).getSignupToken().length).equals(8)
	})

	o("migration helpers are idempotent", function () {
		const oldConfig: any = {_version: 2, _credentials: oldCredentials}
		migrateConfigV2to3(oldConfig)
		o(oldConfig._credentials).deepEquals(expectedCredentials)
		migrateConfig(oldConfig)
		const once = JSON.stringify(oldConfig)
		migrateConfig(oldConfig)
		migrateConfigV2to3(oldConfig)
		o(JSON.stringify(oldConfig)).equals(once)
	})
})
